package com.yeyamo_mobile.api.recommendation_service.domain;import java.time.Instant;
public record Candidate(String sourceId,String targetId,CandidateKind kind,String title,String categoryCode,String regionCode,String countryCode,String languageCode,Double latitude,Double longitude,double popularity,boolean active,Instant publishedAt,Instant updatedAt){public Candidate{if(sourceId==null||sourceId.isBlank()||targetId==null||targetId.isBlank())throw new IllegalArgumentException("candidate identifiers are required");if(kind==null||title==null||title.isBlank())throw new IllegalArgumentException("candidate kind and title are required");if((latitude==null)!=(longitude==null))throw new IllegalArgumentException("coordinates must be provided together");if(latitude!=null&&(latitude < -90||latitude > 90||longitude < -180||longitude > 180))throw new IllegalArgumentException("invalid coordinates");countryCode=countryCode==null?null:countryCode.trim().toUpperCase(java.util.Locale.ROOT);languageCode=languageCode==null?null:languageCode.trim();popularity=Math.max(0,popularity);}public Candidate(String sourceId,String targetId,CandidateKind kind,String title,String categoryCode,String regionCode,Double latitude,Double longitude,double popularity,boolean active,Instant publishedAt,Instant updatedAt){this(sourceId,targetId,kind,title,categoryCode,regionCode,null,null,latitude,longitude,popularity,active,publishedAt,updatedAt);}}
